  "strategies": [
    {
      "bucket": "analytics",
      "type": "game_management",
      "title": "Aggressive 4th-Down Conversion Decision Rules",
      "recommendation": "Adopt aggressive 4th-down go-for-it rules, consistently attempting conversions on 4th-and-3 or shorter past your own 40-yard line and 4th-and-1 anywhere on the field. Eliminate low-value punts and long field goal attempts in these neutral-to-favorable midfield zones.",
      "rationale": "Public win-probability and Expected Points Added (EPA) models consistently show NFL coaches punt and kick field goals far too conservatively, relinquishing measurable expected points per game.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 1.4,
          "interval_95_low": 0.3,
          "interval_95_high": 2.5,
          "shape": "symmetric",
          "tails": "light"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The effect is well-documented in published research with symmetric estimation errors centered around a positive mean and light tails."
        },
        "parameters": {
          "mu": 1.4,
          "sigma": 0.5612,
          "conversion_note": "Derived for normal distribution: mu = 1.40; sigma = (2.50 - 0.30) / (2 * 1.96) = 2.20 / 3.92 = 0.5612."
        },
        "consistency_check": "Confirmed: most_plausible_value (1.40) lies inside [0.30, 2.50], and support is unbounded real."
      }
    },
    {
      "bucket": "analytics",
      "type": "offensive",
      "title": "High-Volume Pre-Snap and Snap-Motion Usage",
      "recommendation": "Incorporate pre-snap or at-the-snap motion on over 75% of offensive dropbacks and runs, prioritizing motion at the snap. Use late motion intentionally to force real-time coverage communication and compromise secondary leverage.",
      "rationale": "Extensive public analytics confirms motion at the snap boosts offensive EPA per play and success rate by revealing coverage indicators and weakening defensive gap integrity.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 1.1,
          "interval_95_low": 0.1,
          "interval_95_high": 2.1,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "Symmetric prior centered around a positive gain, with heavy tails (nu=4) accounting for variation across defensive scheme adjustments."
        },
        "parameters": {
          "nu": 4,
          "mu": 1.1,
          "sigma": 0.3602,
          "conversion_note": "Derived for student_t with nu = 4: mu = 1.10; scale sigma = (2.10 - 0.10) / (2 * 2.776) = 2.00 / 5.552 = 0.3602, using t_{0.975,4} = 2.776."
        },
        "consistency_check": "Confirmed: most_plausible_value (1.10) lies inside [0.10, 2.10], and support is unbounded real."
      }
    },
    {
      "bucket": "analytics",
      "type": "defensive",
      "title": "Early-Down Two-High Safety Shells",
      "recommendation": "Maintain split-safety (two-high) shells pre-snap on 1st and 2nd down at top-tier rates, accepting light boxes against early-down runs to stop deep passes. Avoid rolling extra defenders into the box prior to the snap on early downs.",
      "rationale": "Passing efficiency dominates rushing efficiency on early downs in public analytics; suppressing explosive passes yields greater net EPA defense even if opponent early-down rush yards per carry increase slightly.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.75,
          "interval_95_low": -0.45,
          "interval_95_high": 1.95,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "Heavy-tailed symmetric distribution (nu=7) accounts for fat-tail risk against heavy rushing teams that exploit light boxes for large gains."
        },
        "parameters": {
          "nu": 7,
          "mu": 0.75,
          "sigma": 0.5074,
          "conversion_note": "Derived for student_t with nu = 7: mu = 0.75; scale sigma = (1.95 - (-0.45)) / (2 * 2.365) = 2.40 / 4.730 = 0.5074, using t_{0.975,7} = 2.365."
        },
        "consistency_check": "Confirmed: most_plausible_value (0.75) lies inside [-0.45, 1.95], and support is unbounded real."
      }
    },
    {
      "bucket": "intuition",
      "type": "game_management",
      "title": "Early Second-Half Timeout Calls for Momentum Interruption",
      "recommendation": "Call a defensive timeout early in the 3rd quarter whenever the opponent completes consecutive 15+ yard plays, explicitly breaking offensive play-calling tempo. Use the stoppage to reset defensive personnel and calm panic.",
      "rationale": "Public analytics is silent on offensive momentum and psychological disruption via timeouts. Coaching judgment indicates stopping fast-paced opponent drives prevents compounding multi-play defensive collapses.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.25,
          "interval_95_low": -0.85,
          "interval_95_high": 1.85,
          "shape": "right_skewed",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "skew_normal",
          "justification": "Asymmetric right-skewed prior modeling modest baseline benefit with long upside potential if breaking opponent momentum forces a turnover."
        },
        "parameters": {
          "xi": -0.2,
          "omega": 1.05,
          "alpha": 2.2,
          "conversion_note": "Fit numerically for skew_normal(xi, omega, alpha) with location xi = -0.20, scale omega = 1.05, shape alpha = 2.20 to match mode = 0.25 and 95% interval [-0.85, 1.85]."
        },
        "consistency_check": "Confirmed: most_plausible_value (0.25) lies inside [-0.85, 1.85], and support covers all signed real values."
      }
    },
    {
      "bucket": "intuition",
      "type": "offensive",
      "title": "Heavy-Personnel No-Huddle Deep Sequences",
      "recommendation": "Deploy 13-personnel (1 RB, 3 TE) in sudden 3-to-4 play no-huddle bursts, executing deep play-action vertical routes against heavy defensive personnel forced to stay on the field. Prevent defensive line substitutions and force linebackers into isolated deep coverages.",
      "rationale": "Public models evaluate play-action and personnel groupings independently, but are silent on combining heavy personnel with no-huddle tempo to force mismatches against gassed base defenses.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.5,
          "interval_95_low": -1.1,
          "interval_95_high": 1.5,
          "shape": "left_skewed",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "skew_normal",
          "justification": "Asymmetric left-skewed prior representing downside risk if offensive play-calling stalls or leads to sacks in compressed spaces, balanced by positive modal EV."
        },
        "parameters": {
          "xi": 0.87,
          "omega": 0.98,
          "alpha": -2.0,
          "conversion_note": "Fit numerically for skew_normal(xi, omega, alpha) with location xi = 0.87, scale omega = 0.98, shape alpha = -2.00 to match mode = 0.50 and 95% interval [-1.10, 1.50]."
        },
        "consistency_check": "Confirmed: most_plausible_value (0.50) lies inside [-1.10, 1.50], and support is unbounded real."
      }
    },
    {
      "bucket": "intuition",
      "type": "defensive",
      "title": "Target-Bracket Secondary Options on Third Down",
      "recommendation": "Bracket and double-team the opponent's WR2 or TE1 on 3rd-and-medium, while leaving the WR1 in single coverage with safety leverage to disrupt timing. Force the QB to move off their quick second read into unfamiliar late progressions.",
      "rationale": "Public analytics focuses almost exclusively on double-teaming WR1s; coaching intuition suggests taking away safety-valve secondary options creates QB hesitation that quantitative models do not capture.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.35,
          "interval_95_low": -0.95,
          "interval_95_high": 1.65,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "Heavy-tailed symmetric prior (nu=4) due to high variance; leaving an elite WR1 isolated carries downside potential if the receiver wins quickly."
        },
        "parameters": {
          "nu": 4,
          "mu": 0.35,
          "sigma": 0.4683,
          "conversion_note": "Derived for student_t with nu = 4: mu = 0.35; scale sigma = (1.65 - (-0.95)) / (2 * 2.776) = 2.60 / 5.552 = 0.4683, using t_{0.975,4} = 2.776."
        },
        "consistency_check": "Confirmed: most_plausible_value (0.35) lies inside [-0.95, 1.65], and support spans all signed real numbers."
      }
    }
  ]
